import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Pages in Flows","description":"Show pages as a user interface inside a Flow.","frontmatter":{"title":"Pages in Flows","description":"Show pages as a user interface inside a Flow."},"headers":[],"relativePath":"en/flows/seiten-in-flows.md","filePath":"en/flows/seiten-in-flows.md","lastUpdated":1787319236000}'),o={name:"en/flows/seiten-in-flows.md"};function i(r,e,l,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="pages-in-flows" tabindex="-1">Pages in Flows <a class="header-anchor" href="#pages-in-flows" aria-label="Permalink to &quot;Pages in Flows&quot;">​</a></h1><p>A Flow can show a <a href="/en/seiten/was-sind-seiten">page</a> and wait for input. This turns automations into guided processes involving people — approvals, follow-up questions, multi-stage data entry.</p><h2 id="the-three-steps-involved" tabindex="-1">The three steps involved <a class="header-anchor" href="#the-three-steps-involved" aria-label="Permalink to &quot;The three steps involved&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Role</th></tr></thead><tbody><tr><td><strong>Show page</strong> (trigger)</td><td><em>Start Flow and load page</em></td></tr><tr><td><strong>Show page</strong> (action)</td><td><em>Displays a page for user interaction</em></td></tr><tr><td><strong>Create link to page</strong></td><td><em>Creates a link to a page in the Flow</em></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Two steps share the same name</p><p>The <strong>trigger</strong> starts the Flow with a page. The <strong>action</strong> interrupts it partway through.</p><p>Pay attention to which tab you&#39;re in — <em>Trigger</em> or <em>Actions</em>.</p></div><h2 id="a-page-as-the-entry-point" tabindex="-1">A page as the entry point <a class="header-anchor" href="#a-page-as-the-entry-point" aria-label="Permalink to &quot;A page as the entry point&quot;">​</a></h2><p>The <strong>Show page</strong> trigger starts the Flow as soon as someone submits a page.</p><p>The configuration explains:</p><blockquote><p><em>Use the link below to open the first page of our Flow. As soon as this page is submitted, the Flow will start.</em></p></blockquote><p>And on distributing it:</p><blockquote><p><em>You can also pass on this link, for example as a QR code for easy access, or link to it on your website or intranet.</em></p></blockquote><p><strong>Suited for:</strong> incident reports, orders, applications — anything that starts with an input form.</p><h2 id="a-page-in-the-middle-of-a-process" tabindex="-1">A page in the middle of a process <a class="header-anchor" href="#a-page-in-the-middle-of-a-process" aria-label="Permalink to &quot;A page in the middle of a process&quot;">​</a></h2><p>The <strong>Show page</strong> action pauses the Flow. It continues once someone submits the page.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: Entry via form</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Email                     →  &quot;Please review&quot;</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Show page                 →  Flow waits for approval</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Update entry               →  set status</span></span></code></pre></div><p>While waiting, the run has the status <strong>Waiting</strong> in the <a href="/en/flows/durchlaufhistorie">history</a>.</p><div class="warning custom-block"><p class="custom-block-title">&quot;Show page&quot; requires someone to be present</p><p>The action shows the page to the person currently operating the Flow. For someone who only has time later, you need a link instead.</p></div><h2 id="asynchronous-via-a-link" tabindex="-1">Asynchronous via a link <a class="header-anchor" href="#asynchronous-via-a-link" aria-label="Permalink to &quot;Asynchronous via a link&quot;">​</a></h2><p><strong>Create link to page</strong> generates a link to the running instance. You send this by email — the person opens it whenever it suits them.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: Entry was changed   (Status = &quot;Approval needed&quot;)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Create link to page           →  link to this run</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Email                          →  sends the link</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Show page                      →  Flow waits</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Update entry</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">The path to real approval processes</p><p>This combination is the difference between an automation that only runs while someone is watching, and a process that works over multiple days.</p><p>The approving person gets an email, clicks the link, sees the data, decides — and the Flow continues.</p></div><h2 id="preparing-a-page" tabindex="-1">Preparing a page <a class="header-anchor" href="#preparing-a-page" aria-label="Permalink to &quot;Preparing a page&quot;">​</a></h2><p>A page for a Flow differs from a portal:</p><div class="tip custom-block"><p class="custom-block-title">Show only what matters</p><ul><li><strong>Show context</strong>: what needs to be decided? Set the relevant fields to <em>Not editable</em>.</li><li><strong>Capture the decision</strong>: the <strong>Decision</strong> block, with custom labels for Yes and No, is clearer here than a checkmark.</li><li><strong>Show follow-up questions conditionally</strong>: a reason field on rejection — via <a href="/en/seiten/sichtbarkeit">conditional visibility</a>.</li><li><strong>Assign keys</strong>: you access the entered values later via the block&#39;s <strong>key</strong>.</li></ul></div><p>→ <a href="/en/seiten/eingabebloecke">Input blocks</a> · <a href="/en/flows/daten-zwischen-schritten">Data between steps</a></p><h2 id="editing-the-page" tabindex="-1">Editing the page <a class="header-anchor" href="#editing-the-page" aria-label="Permalink to &quot;Editing the page&quot;">​</a></h2><p>In the step editor, there&#39;s a <strong>Edit page</strong> tab next to <strong>Settings</strong>. So you don&#39;t need to switch to the Pages area.</p><p>Conversely, a page&#39;s settings show under <strong>Used in Flows</strong> which Flows display it.</p><h2 id="when-no-page-is-assigned" tabindex="-1">When no page is assigned <a class="header-anchor" href="#when-no-page-is-assigned" aria-label="Permalink to &quot;When no page is assigned&quot;">​</a></h2><blockquote><p><em>No UI has been set up for this step. If you need a UI, you can add one in the Flow Editor.</em></p></blockquote><div class="danger custom-block"><p class="custom-block-title">Most common cause: the page was deleted</p><p>Always check the <strong>Used in Flows</strong> section before deleting a page. A deleted page breaks every Flow that shows it — and affected users only see <em>This process step could not be loaded</em>.</p></div><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>For Flow-bound pages, there&#39;s a dedicated test path: <strong>With data from the Flow form</strong> — <em>Open the form and test with submitted data</em>.</p><div class="tip custom-block"><p class="custom-block-title">The most realistic test</p><p>Other test types plug in artificial data. This path goes through the real interface and also surfaces errors in the page itself — missing keys, incorrectly set required fields, visibility conditions that never apply.</p></div><p>→ <a href="/en/flows/testen">Testing Flows</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/trigger">Trigger</a></li><li><a href="/en/flows/aktionen">Actions</a></li><li><a href="/en/seiten/was-sind-seiten">What are Pages</a></li></ul>`,37)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
